// Custom hash for tuple to avoid compilation issues
namespace std {
template<>
struct hash<std::tuple<double, double, double>> {
    std::size_t operator()(const std::tuple<double, double, double>& t) const {
        // Simple hash combining the three values
        std::size_t h1 = std::hash<double>{}(std::get<0>(t));
        std::size_t h2 = std::hash<double>{}(std::get<1>(t));
        std::size_t h3 = std::hash<double>{}(std::get<2>(t));
        return h1 ^ (h2 << 1) ^ (h3 << 2);
    }
};
}

namespace mkt {

// Observer/Observable pair with proper lifetime management
class Observable;
class Observer : public std::enable_shared_from_this<Observer> {
public:
    virtual ~Observer() = default;
    virtual void update() = 0;
public:
    void observe(const std::shared_ptr<Observable>& o);
    void stop_observing(const std::shared_ptr<Observable>& o);
};

class Observable {
public:
    virtual ~Observable() = default;
    void notify();
protected:
    std::set<std::weak_ptr<Observer>> observers_;
    mutable std::mutex mutex_;
    friend class Observer;
};

// A mutable market value. set() with the current value does nothing.
class Quote : public Observable {
public:
    explicit Quote(double v);
    double value() const;
    void set(double v);
private:
    double value_;
    mutable std::mutex mutex_;
};

// LazyObject with caching
class LazyObject {
public:
    virtual ~LazyObject() = default;
    virtual double value() = 0;
    void invalidate() { valid_ = false; }
protected:
    mutable std::atomic<bool> valid_{false};
    mutable std::mutex mutex_;
};

// A factory for engines
class Engine {
public:
    virtual ~Engine() = default;
    virtual double price(double spot, double strike, double vol) = 0;
};

// A self-registering factory
template<typename T>
class Factory {
public:
    static void register_type(const std::string& name, std::function<std::unique_ptr<T>()> factory);
    static std::unique_ptr<T> create(const std::string& name);
    static std::vector<std::string> list();
private:
    static std::unordered_map<std::string, std::function<std::unique_ptr<T>()>> factories_;
};

// A decorator for engines
class MemoEngine : public Engine {
public:
    MemoEngine(std::unique_ptr<Engine> inner);
    double price(double spot, double strike, double vol) override;
private:
    std::unique_ptr<Engine> inner_;
    mutable std::unordered_map<std::tuple<double, double, double>, double> cache_;
    mutable std::mutex mutex_;
};

// A macro to register engines
#define REGISTER_ENGINE(name, type) \
    static auto name##_registrar = []() { \
        mkt::Factory<mkt::Engine>::register_type(#name, []() { return std::make_unique<type>(); }); \
        return 0; \
    }();

} // namespace mkt

